def quiz():
    q = f'''<div class="qz">{pas(3,5)}<div class="verre q"><small>Question 3 sur 5</small><b>Quelle formule renvoie « Atteint » si les ventes dépassent 100 ?</b></div>
<div class="quiz-o"><div class="o"><i>A</i>=RECHERCHEV(100;A2;1)</div><div class="o ok"><i>{ic("valider","xs")}</i>=SI(B2&gt;100;"Atteint";"Non")</div><div class="o"><i>C</i>=SOMME(B2;100)</div></div>
<div class="expl"><b>Bonne réponse</b>SI teste la condition B2 &gt; 100, puis renvoie le premier texte si elle est vraie.</div>
<div class="lnav"><span></span><a class="bt p m">Question suivante{ic("suivant","xs")}</a></div></div>'''
    pl_ = ''.join(f'<div class="l {c}"><i>{ic("valider","xs") if c == "ok" else n}</i><span>Question {n}</span></div>' for n, c in [(1,'ok'),(2,'ok'),(3,'on'),(4,''),(5,'')])
    return wh('Quiz · Module 2', 'Les formules · 4 bonnes réponses sur 5 pour valider') + f'<div class="ql">{q}<div class="verre plan"><h4>Questions<span>3 sur 5</span></h4>{pl_}</div></div>'
